package com.agentguard.controller;
import com.agentguard.dto.UserResponse; import com.agentguard.service.UserService; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import java.math.BigDecimal; import java.time.Instant; import static org.mockito.ArgumentMatchers.any; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(UserController.class) class UserControllerTest { @Autowired MockMvc mvc; @MockBean UserService service; @Test void createsUser() throws Exception { Mockito.when(service.create(any())).thenReturn(new UserResponse(1L,"Ada","ada@example.com",new BigDecimal("100.00"),new BigDecimal("25.00"),Instant.parse("2026-01-01T00:00:00Z")));mvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Ada\",\"email\":\"ada@example.com\",\"spendingLimit\":100.00,\"hourlySpendingLimit\":25.00}")).andExpect(status().isCreated()).andExpect(jsonPath("$.id").value(1)).andExpect(jsonPath("$.email").value("ada@example.com"));} }
